21	// ============================================================================
22	// MODEL CONFIGURATION
23	// ============================================================================
24	
25	export type ClaudeModel = 'haiku' | 'sonnet' | 'opus';
26	
27	export const CLAUDE_MODELS = {
28	  haiku: 'claude-3-haiku-20240307',
29	  sonnet: MODELS.generation,
30	  opus: MODELS.generation, // Using Sonnet as Opus equivalent for now
31	} as const;
