126	  const hasRelationalMarkers = /\b(you always|you never|i can't|i won't|this is over|i'm done|last chance|or else)\b/i.test(text);
127	  const hasIdentityMarkers = /\b(i'm not good enough|i'm worthless|nobody cares|everyone hates|i'm a failure|i don't matter)\b/i.test(text);
