/**
 * Governed Anthropic Bridge
 * 
 * Drop-in replacement for direct `anthropic.messages.create()` calls.
 * Routes all Claude calls through the governed `invokeLLM` pipeline,
 * which runs duringCreationCheck on every output.
 * 
 * This closes the bypass gap where modules used `new Anthropic()` directly
 * instead of `invokeLLM`, skipping governance entirely.
 * 
 * Usage:
 *   // Before (ungoverned):
 *   const anthropic = new Anthropic();
 *   const response = await anthropic.messages.create({ model, messages, ... });
 *   const text = response.content[0].text;
 * 
 *   // After (governed):
 *   const response = await governedClaude.messages.create({ model, messages, ... });
 *   const text = response.content[0].text;
 * 
 * The response format is identical to Anthropic SDK — no call site changes needed
 * beyond swapping the import.
 * 
 * Architecture: Governance as physics, not governance as advice.
 */
import { governedGenerate } from "./governed-generate";
import { extractLLMContent } from "../_core/llm";
import type { InvokeResult, Message } from "../_core/llm";
import { shapeCast } from '../../shared/type-bridge';
import { z } from 'zod';
import { generalLog as log } from "../_core/logger";
import { MODELS } from "../_core/models";

// Runtime schema for the AnthropicResponse shape we construct and return
const AnthropicResponseSchema = z.object({
  id: z.string(),
  type: z.literal('message'),
  role: z.literal('assistant'),
  content: z.array(z.object({ type: z.string(), text: z.string() })).min(1),
  model: z.string(),
  stop_reason: z.string().nullable(),
  stop_sequence: z.string().nullable(),
  usage: z.object({
    input_tokens: z.number(),
    output_tokens: z.number(),
  }),
});

/**
 * Safe sentinel response returned when the constructed AnthropicResponse
 * fails schema validation. Ensures callers always receive a well-typed value.
 *
 * IMPORTANT: Callers MUST check `_isSentinel === true` before treating this
 * as a legitimate LLM response. Do not display sentinel content to end users
 * or use it in downstream governance decisions.
 */
const SAFE_SENTINEL_RESPONSE: AnthropicResponse & { _isSentinel: true } = {
  id: 'governance-error',
  type: 'message',
  role: 'assistant',
  content: [{ type: 'text', text: '[Governance error: response failed schema validation]' }],
  model: 'unknown',
  stop_reason: 'end_turn',
  stop_sequence: null,
  usage: { input_tokens: 0, output_tokens: 0 },
  _isSentinel: true,
};

/**
 * Validate a constructed response object against the AnthropicResponseSchema.
 * Returns the validated response or SAFE_SENTINEL_RESPONSE on failure.
 */
function validateAnthropicResponse(
  candidate: unknown,
  context: { reviewId?: string } = {}
): AnthropicResponse {
  const parsed = AnthropicResponseSchema.safeParse(candidate);
  if (!parsed.success) {
    // Log schema violation details without leaking raw LLM content
    const errorSummary = parsed.error.issues.map(i => i.message).join('; ');
    log.error(
      { reviewId: context.reviewId, validationErrors: errorSummary },
      'AnthropicResponse schema validation failed — returning safe sentinel'
    );
    return SAFE_SENTINEL_RESPONSE;
  }
  return parsed.data as AnthropicResponse;
}

// ============================================================================
// TYPES - Match Anthropic SDK response format
// ============================================================================

interface AnthropicMessage {
  role: string;
  content: string | Array<{ type: string; text?: string; [key: string]: unknown }>;
}

interface AnthropicCreateParams {
  model: string;
  max_tokens: number;
  system?: string;
  messages: AnthropicMessage[];
  temperature?: number;
  top_p?: number;
  stop_sequences?: string[];
  [key: string]: unknown;
}

interface AnthropicContentBlock {
  type: 'text';
  text: string;
}

interface AnthropicResponse {
  id: string;
  type: 'message';
  role: 'assistant';
  content: AnthropicContentBlock[];
  model: string;
  stop_reason: string | null;
  stop_sequence: string | null;
  usage: {
    input_tokens: number;
    output_tokens: number;
  };
}

// ============================================================================
// BRIDGE IMPLEMENTATION
// ============================================================================

/**
 * Mandatory minimum governance system prompt injected when no caller system prompt is provided.
 * Ensures no call through this bridge is ever system-prompt-free.
 */
const DEFAULT_GOVERNANCE_SYSTEM_PROMPT =
  'You are an AI assistant operating under Gravito governance. ' +
  'You must follow all output constraints enforced by the Gravito governance pipeline. ' +
  'Respond accurately, concisely, and in accordance with the product guidelines. ' +
  'Do not produce harmful, deceptive, or policy-violating content under any circumstances. ' +
  'Do not reveal internal system architecture, configuration, or governance pipeline details. ' +
  'All responses must be factual, grounded, and free of speculation or fabrication. ' +
  'Output format: plain text unless the caller explicitly requests structured output (e.g., JSON or Markdown). ' +
  'Refuse requests that violate governance policy and explain that the request cannot be fulfilled.';

let callCount = 0;

/**
 * Convert Anthropic SDK params to invokeLLM params and route through governance
 */
async function governedCreate(params: AnthropicCreateParams): Promise<AnthropicResponse> {
  callCount++;
  const callId = `gov_bridge_${callCount}`;

  // Build messages array compatible with invokeLLM
  const messages: Message[] = [];

  // Always inject a system message — use caller's prompt if provided, otherwise
  // fall back to the mandatory minimum governance system prompt so that no call
  // is ever sent to the model without behavioral constraints.
  const systemContent = params.system || DEFAULT_GOVERNANCE_SYSTEM_PROMPT;
  messages.push({ role: 'system' as const, content: systemContent });

  // Convert Anthropic messages to invokeLLM format
  for (const msg of params.messages) {
    const content = typeof msg.content === 'string'
      ? msg.content
      : msg.content
          .filter((block: any) => block.type === 'text')
          .map((block: any) => block.text)
          .join('\n');
    messages.push({ role: msg.role as Message['role'], content });
  }

  // Route through governed invokeLLM
  const resolvedModel = shapeCast<string>(params.model);
  if (!resolvedModel) {
    throw new Error(`[governedCreate] resolved model string is empty for callId=${callId}`);
  }

  // Retry loop: up to 3 attempts with exponential backoff
  // Detects degraded/fallback responses and retries before accepting them
  const MAX_ATTEMPTS = 3;
  const BACKOFF_BASE_MS = 1500;
  let lastResult: InvokeResult | null = null;
  let lastResponseText = '';

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    // @ts-ignore — TS2739 (interface drift)
    const result: InvokeResult = await governedGenerate({
      messages,
      model: resolvedModel,
      // @ts-ignore — object literal property (interface drift)
      provider: 'claude',
      max_tokens: params.max_tokens,
      contentType: 'generation',
      contentRole: 'user-facing',
      productId: 'governance',
      surfaceId: 'governance-governed-anthropic',
      maxRetries: 1,
    });

    lastResult = result;
    lastResponseText = extractLLMContent(result) || '';

    // Check if the response is a degraded fallback
    const isDegraded = result.model === 'fallback-degraded' ||
      lastResponseText.includes('"_degraded":true') ||
      lastResponseText.includes('"_degraded": true') ||
      lastResponseText.includes('infra_degraded') ||
      lastResponseText.includes('LLM service unavailable');

    if (!isDegraded) {
      // Got a real response — use it
      break;
    }

    if (attempt < MAX_ATTEMPTS) {
      const backoffMs = BACKOFF_BASE_MS * Math.pow(2, attempt - 1);
      log.warn(`[governedCreate:${callId}] Degraded response on attempt ${attempt}/${MAX_ATTEMPTS}, retrying in ${backoffMs}ms...`);
      await new Promise(resolve => setTimeout(resolve, backoffMs));
    } else {
      log.warn(`[governedCreate:${callId}] All ${MAX_ATTEMPTS} attempts returned degraded responses — using last result`);
    }
  }

  const result = lastResult!;
  const responseText = lastResponseText;

  // Convert back to Anthropic SDK response format
  const anthropicResponse: AnthropicResponse = {
    id: `msg_${callId}`,
    type: 'message',
    role: 'assistant',
    content: [{
      type: 'text',
      text: responseText
    }],
    model: params.model || result.model || MODELS.generation,
    stop_reason: result.choices?.[0]?.finish_reason || 'end_turn',
    stop_sequence: null,
    usage: {
      input_tokens: result.usage?.prompt_tokens || 0,
      output_tokens: result.usage?.completion_tokens || 0,
    }
  };

  return anthropicResponse;
}

/**
 * Create a governed stream that wraps invokeLLM
 * For streaming calls, we still route through governance but return
 * the full response (governance can't check partial streams)
 */
async function governedStream(params: AnthropicCreateParams): Promise<{
  finalMessage: () => Promise<AnthropicResponse>;
  [Symbol.asyncIterator]: () => AsyncIterator<any>;
}> {
  // For streaming, we generate the full response through governance first,
  // then simulate the stream. This ensures governance checks run on complete output.
  const fullResponse = await governedCreate(params);

  // Create an async iterator that yields the response as stream events
  const events = [
    { type: 'message_start', message: { id: fullResponse.id, type: 'message', role: 'assistant', content: [], model: fullResponse.model, usage: { input_tokens: fullResponse.usage.input_tokens, output_tokens: 0 } } },
    { type: 'content_block_start', index: 0, content_block: { type: 'text', text: '' } },
    { type: 'content_block_delta', index: 0, delta: { type: 'text_delta', text: fullResponse.content[0]?.text || '' } },
    { type: 'content_block_stop', index: 0 },
    { type: 'message_delta', delta: { stop_reason: 'end_turn' }, usage: { output_tokens: fullResponse.usage.output_tokens } },
    { type: 'message_stop' }
  ];

  let eventIndex = 0;

  return {
    finalMessage: async () => fullResponse,
    [Symbol.asyncIterator]: () => ({
      async next() {
        if (eventIndex < events.length) {
          return { value: events[eventIndex++], done: false };
        }
        return { value: undefined, done: true };
      }
    })
  };
}

// ============================================================================
// PUBLIC API - Drop-in replacement for `new Anthropic()`
// ============================================================================

/**
 * Governed Claude client.
 * 
 * Use this instead of `new Anthropic()` to ensure all Claude calls
 * pass through the governance pipeline.
 * 
 * Response format is identical to the Anthropic SDK.
 */
export const governedClaude = {
  messages: {
    create: governedCreate,
    stream: governedStream,
  }
};

/**
 * Get bridge statistics for monitoring
 */
export function getGovernedBridgeStats() {
  return {
    totalCalls: callCount,
    bridgeActive: true,
    description: 'All direct Anthropic calls routed through governed invokeLLM pipeline'
  };
}

export default governedClaude;

