 * - Haiku: Fast, lightweight analysis for simple messages
 * - Sonnet: Balanced speed/quality for standard analysis
 * - Opus: Deep analysis with extended thinking for complex emotional situations
 */

// Governed: routed through invokeLLM governance pipeline
import { governedClaude } from '../../governance/governed-anthropic';
import { generalLog } from '../../_core/logger';
import { MODELS } from '../../_core/models';

// Initialize Anthropic client using the environment variable
const anthropic = governedClaude;

// ============================================================================
// MODEL CONFIGURATION
// ============================================================================

export type ClaudeModel = 'haiku' | 'sonnet' | 'opus';

export const CLAUDE_MODELS = {
  haiku: 'claude-3-haiku-20240307',
  sonnet: MODELS.generation,
  opus: MODELS.generation, // Using Sonnet as Opus equivalent for now
} as const;

export interface ModelConfig {
  model: ClaudeModel;
  maxTokens: number;
  useExtendedThinking: boolean;
  thinkingBudget?: number;
}

// Default configurations for different use cases
export const MODEL_CONFIGS: Record<string, ModelConfig> = {
  // Fast analysis for simple, low-risk messages
  fast: {
    model: 'haiku' as ClaudeModel,
    maxTokens: 1024,
    useExtendedThinking: false,
    thinkingBudget: undefined,
  },
  // Standard analysis for most messages
  standard: {
    model: 'sonnet' as ClaudeModel,
    maxTokens: 2048,
    useExtendedThinking: false,
    thinkingBudget: undefined,
  },
  // Deep analysis for complex emotional situations
  deep: {
    model: 'sonnet' as ClaudeModel,
    maxTokens: 4096,
    useExtendedThinking: true,
    thinkingBudget: 2048,
  },
  // Critical analysis for high-risk situations (escalation, rupture)
  critical: {
    model: 'sonnet' as ClaudeModel,
    maxTokens: 8192,
    useExtendedThinking: true,
    thinkingBudget: 4096,
  },
};

// ============================================================================
// TYPES
// ============================================================================

export interface ClaudeMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface ClaudeInvokeParams {
  messages: ClaudeMessage[];
  system?: string;
  maxTokens?: number;
  model?: ClaudeModel;
  useExtendedThinking?: boolean;
  thinkingBudget?: number;
}

export interface ClaudeInvokeResult {
  content: string;
  thinking?: string;
  model: string;
  stopReason: string | null;
  usage: {
    inputTokens: number;
    outputTokens: number;
  };
}

// ============================================================================
// COMPLEXITY DETECTION
// ============================================================================

/**
 * Analyze message complexity to determine appropriate model
 */
export function detectComplexity(
  text: string,
  riskLevel?: number,
  escalationScore?: number
): 'fast' | 'standard' | 'deep' | 'critical' {
  // High risk situations always get critical analysis
  if (riskLevel !== undefined && riskLevel > 0.7) {
    return 'critical';
  }

  // Escalation risk triggers deep analysis
  if (escalationScore !== undefined && escalationScore > 0.5) {
    return 'deep';
  }

  // Text-based complexity detection
  const wordCount = text.split(/\s+/).length;
  const hasEmotionalMarkers = /\b(angry|frustrated|upset|hurt|scared|anxious|worried|devastated|furious|hopeless|desperate)\b/i.test(text);
  const hasRelationalMarkers = /\b(you always|you never|i can't|i won't|this is over|i'm done|last chance|or else)\b/i.test(text);
  const hasIdentityMarkers = /\b(i'm not good enough|i'm worthless|nobody cares|everyone hates|i'm a failure|i don't matter)\b/i.test(text);
  const hasUrgencyMarkers = /\b(immediately|right now|urgent|emergency|asap|can't wait)\b/i.test(text);

  // Critical: Identity threats or extreme urgency
  if (hasIdentityMarkers || (hasUrgencyMarkers && hasEmotionalMarkers)) {
    return 'critical';
  }

  // Deep: Strong emotional or relational content
  if (hasEmotionalMarkers && hasRelationalMarkers) {
    return 'deep';
  }

  // Standard: Moderate complexity
  if (hasEmotionalMarkers || hasRelationalMarkers || wordCount > 50) {
    return 'standard';
  }

  // Fast: Simple messages
  return 'fast';
}

// ============================================================================
// CORE INVOCATION
// ============================================================================

/**
 * Invoke Claude with extended thinking for deep emotional analysis
 */
async function invokeWithExtendedThinking(
  params: ClaudeInvokeParams
): Promise<ClaudeInvokeResult> {
  const modelId = CLAUDE_MODELS[params.model || 'sonnet'];
  const thinkingBudget = params.thinkingBudget || 2048;

  const response = await anthropic.messages.create({
    model: modelId,
    max_tokens: (params.maxTokens || 4096) + thinkingBudget,
    thinking: {
      type: 'enabled',
      budget_tokens: thinkingBudget,
    },
    system: params.system || 'You are an expert at analyzing emotional and relational dynamics in text. Extract precise numeric features.',
    messages: params.messages,
  });

  // Extract thinking and text content
  let thinkingContent = '';
  let textContent = '';

  for (const block of response.content) {
    if ((block as unknown as Record<string, unknown>).type === 'thinking') {
      thinkingContent = (block as unknown as Record<string, unknown>).thinking;
    } else if (block.type === 'text') {
      textContent = block.text;
    }
  }

  return {
    content: textContent,
    thinking: thinkingContent,
    model: response.model,
    stopReason: response.stop_reason,
    usage: {
      inputTokens: response.usage.input_tokens,
      outputTokens: response.usage.output_tokens,
    },
  };
}

/**
 * Invoke Claude without extended thinking (standard mode)
 */
async function invokeStandard(
  params: ClaudeInvokeParams
): Promise<ClaudeInvokeResult> {
  const modelId = CLAUDE_MODELS[params.model || 'sonnet'];

  const response = await anthropic.messages.create({
    model: modelId,
    max_tokens: params.maxTokens || 2048,
    system: params.system || 'You are an expert at analyzing emotional and relational dynamics in text. Extract precise numeric features.',
    messages: params.messages,
  });

  // Extract text content
  const textBlock = response.content.find(block => block.type === 'text');
  const content = textBlock && textBlock.type === 'text' ? textBlock.text : '';

  return {
    content,
    model: response.model,
    stopReason: response.stop_reason,
    usage: {
      inputTokens: response.usage.input_tokens,
      outputTokens: response.usage.output_tokens,
    },
  };
}

/**
 * Main invocation function - automatically selects thinking mode
 */
export async function invokeClaudeForDynamics(
  params: ClaudeInvokeParams
): Promise<ClaudeInvokeResult> {
  if (params.useExtendedThinking) {
    return invokeWithExtendedThinking(params);
  }
  return invokeStandard(params);
}

/**
 * Smart invocation - automatically detects complexity and selects model
 */
export async function invokeClaudeSmart(
  text: string,
  systemPrompt: string,
  riskLevel?: number,
  escalationScore?: number
): Promise<ClaudeInvokeResult> {
  const complexity = detectComplexity(text, riskLevel, escalationScore);
  const config = MODEL_CONFIGS[complexity];

  generalLog.info(`[Claude] Using ${complexity} mode (${config.model}, thinking: ${config.useExtendedThinking})`);

  return invokeClaudeForDynamics({
    messages: [{ role: 'user', content: text }],
    system: systemPrompt,
    model: config.model,
    maxTokens: config.maxTokens,
    useExtendedThinking: config.useExtendedThinking,
    thinkingBudget: config.thinkingBudget,
  });
}

// ============================================================================
// COMPATIBILITY WRAPPER
// ============================================================================

/**
 * Wrapper that matches the invokeLLM interface for drop-in replacement
 */
export async function invokeClaudeLLM(params: {
  messages: Array<{ role: string; content: string }>;
  model?: ClaudeModel;
  useExtendedThinking?: boolean;
  thinkingBudget?: number;
}): Promise<{
  choices: Array<{
    message: {
      content: string;
      thinking?: string;
    };
  }>;
}> {
  // Convert messages to Claude format
  const systemMessage = params.messages.find(m => m.role === 'system');
  const otherMessages = params.messages.filter(m => m.role !== 'system');

  const claudeMessages: ClaudeMessage[] = otherMessages.map(m => ({
    role: m.role === 'assistant' ? 'assistant' : 'user',
    content: m.content,
  }));

  const result = await invokeClaudeForDynamics({
    messages: claudeMessages,
    system: systemMessage?.content,
    model: params.model || 'sonnet',
    maxTokens: 2048,
    useExtendedThinking: params.useExtendedThinking,
    thinkingBudget: params.thinkingBudget,
  });

  // Return in the same format as invokeLLM
  return {
    choices: [
      {
        message: {
          content: result.content,
          thinking: result.thinking,
        },
      },
    ],
  };
}

// ============================================================================
// SPECIALIZED ANALYSIS FUNCTIONS
// ============================================================================

/**
 * Deep emotional analysis with extended thinking
 * Used for high-risk situations requiring careful consideration
 */
export async function analyzeEmotionalDynamicsDeep(
  text: string,
  conversationHistory: string,
  currentRiskLevel: number
): Promise<{
  analysis: string;
  thinking: string;
  recommendations: string[];
}> {
  const systemPrompt = `You are an expert clinical psychologist and content governance specialist.
Analyze the emotional dynamics in this conversation with deep consideration.

Current risk level: ${(currentRiskLevel * 100).toFixed(0)}%

Consider:
1. Underlying emotional needs not explicitly stated
2. Identity threats or core wounds being triggered
3. Patterns of escalation or de-escalation
4. Repair opportunities and timing
5. The safest path forward

Provide your analysis as JSON:
{
  "analysis": "Your detailed analysis of the emotional dynamics",
  "recommendations": ["Specific actionable recommendations"]
}`;

  const result = await invokeClaudeForDynamics({
    messages: [{
      role: 'user',
      content: `CONVERSATION HISTORY:\n${conversationHistory}\n\nCURRENT MESSAGE:\n${text}`,
    }],
    system: systemPrompt,
    model: 'sonnet',
    maxTokens: 4096,
    useExtendedThinking: true,
    thinkingBudget: 4096,
  });

  // Parse the response
  try {
    const parsed = JSON.parse(result.content);
    return {
      analysis: parsed.analysis || result.content,
      thinking: result.thinking || '',
      recommendations: parsed.recommendations || [],
    };
  } catch {
    return {
      analysis: result.content,
      thinking: result.thinking || '',
      recommendations: [],
    };
  }
}

/**
 * Crisis intervention analysis
 * Used when rupture or severe escalation is detected
 */
export async function analyzeCrisisIntervention(
  text: string,
  conversationHistory: string,
  riskSurface: {
    escalation: number;
    rupture: number;
    repair: number;
  }
): Promise<{
  interventionType: 'de-escalate' | 'validate' | 'boundary' | 'repair' | 'disengage';
  urgency: 'low' | 'medium' | 'high' | 'critical';
  suggestedResponse: string;
  reasoning: string;
}> {
  const systemPrompt = `You are a crisis intervention specialist with expertise in de-escalation.

RISK ASSESSMENT:
- Escalation Risk: ${(riskSurface.escalation * 100).toFixed(0)}%
- Rupture Risk: ${(riskSurface.rupture * 100).toFixed(0)}%
- Repair Probability: ${(riskSurface.repair * 100).toFixed(0)}%

Analyze this situation and recommend the safest intervention.

Return JSON:
{
  "interventionType": "de-escalate" | "validate" | "boundary" | "repair" | "disengage",
  "urgency": "low" | "medium" | "high" | "critical",
  "suggestedResponse": "A carefully crafted response that addresses the emotional needs",
  "reasoning": "Why this intervention is appropriate"
}`;

  const result = await invokeClaudeForDynamics({
    messages: [{
      role: 'user',
      content: `CONVERSATION HISTORY:\n${conversationHistory}\n\nCURRENT MESSAGE:\n${text}`,
    }],
    system: systemPrompt,
    model: 'sonnet',
    maxTokens: 4096,
    useExtendedThinking: true,
    thinkingBudget: 8192, // Maximum thinking for crisis situations
