  try {
    return JSON.parse(result.content);
  } catch {
    return {
      interventionType: 'validate',
      urgency: 'medium',
      suggestedResponse: 'I hear you, and I want to understand what you\'re going through.',
      reasoning: 'Default to validation when analysis fails',
    };
  }
}

